//! Client contains internal traits that are used by code generated for
//! contract clients, so that the compiler resolves the types the client uses
//! from the contract's types, rather than the macros deciding them from how
//! the types are written.
//!
//! [`Type`] gives the types a client returns for a contract function's return
//! type.
//!
//! The trait is implemented for every type that has a type in the contract
//! spec, and for the types generated by the contracttype and contracterror
//! macros. Each type is returned by a client as itself, except a
//! [`crate::crypto::Hash`], which is returned as a [`crate::BytesN`], because a
//! client can't guarantee the bytes it receives came from a secure
//! cryptographic hash function. Types that contain other types, such as
//! `Option`, `Vec`, and tuples, are returned containing the types their
//! contents are returned as. This is consistent with the contract spec, which
//! has a `Hash` as a `BytesN`, and so with clients generated from the spec.
//!
//! A contract function that returns a `Result` is called by a client fn that
//! returns its ok type, and a try client fn that also returns its error type.

use crate::{
    crypto::{
        bls12_381::{Bls12381Fp, Bls12381Fp2, Bls12381Fr, Bls12381G1Affine, Bls12381G2Affine},
        bn254::{Bn254Fp, Bn254Fr, Bn254G1Affine, Bn254G2Affine},
        Hash,
    },
    Address, Bytes, BytesN, Duration, Env, Error, Map, MuxedAddress, String, Symbol, Timepoint,
    TryFromVal, Val, Vec, I256, U256,
};

#[diagnostic::on_unimplemented(
    message = "`{Self}` cannot be used as a contract function return type",
    label = "not a contract function return type",
    note = "contract function return types must be types supported by the contract spec, such as types marked `#[contracttype]`"
)]
pub trait Type {
    /// The type a client returns a value of this type as, including where the
    /// value is contained in another type.
    type Output: TryFromVal<Env, Val>;
    /// The type a client fn returns for a contract function returning this
    /// type. For a `Result` it is the ok type.
    type Ok: TryFromVal<Env, Val>;
    /// The error type a try client fn returns for a contract function
    /// returning this type. For a `Result` it is the error type.
    type Err;
}

macro_rules! impl_client_type_as_self {
    ($($t:ty),* $(,)?) => {
        $(
            impl Type for $t {
                type Output = Self;
                type Ok = Self;
                type Err = Error;
            }
        )*
    };
}

impl_client_type_as_self! {
    Val,
    bool,
    (),
    Error,
    u32,
    i32,
    u64,
    i64,
    Timepoint,
    Duration,
    u128,
    i128,
    U256,
    I256,
    Bytes,
    String,
    Symbol,
    Address,
    MuxedAddress,
    Bls12381Fp,
    Bls12381Fp2,
    Bls12381G1Affine,
    Bls12381G2Affine,
    Bls12381Fr,
    Bn254Fp,
    Bn254G1Affine,
    Bn254G2Affine,
    Bn254Fr,
}

impl<const N: usize> Type for BytesN<N> {
    type Output = Self;
    type Ok = Self;
    type Err = Error;
}

impl<const N: usize> Type for Hash<N> {
    type Output = BytesN<N>;
    type Ok = BytesN<N>;
    type Err = Error;
}

impl<T: Type> Type for Option<T> {
    type Output = Option<T::Output>;
    type Ok = Option<T::Output>;
    type Err = Error;
}

impl<T: Type, E: Type> Type for Result<T, E>
where
    Result<T::Output, E::Output>: TryFromVal<Env, Val>,
{
    type Output = Result<T::Output, E::Output>;
    type Ok = T::Output;
    type Err = E;
}

impl<T: Type> Type for Vec<T>
where
    Vec<T::Output>: TryFromVal<Env, Val>,
{
    type Output = Vec<T::Output>;
    type Ok = Vec<T::Output>;
    type Err = Error;
}

impl<K: Type, V: Type> Type for Map<K, V>
where
    Map<K::Output, V::Output>: TryFromVal<Env, Val>,
{
    type Output = Map<K::Output, V::Output>;
    type Ok = Map<K::Output, V::Output>;
    type Err = Error;
}

macro_rules! impl_client_type_for_tuple {
    ($($t:ident),+) => {
        impl<$($t: Type),+> Type for ($($t,)+) {
            type Output = ($($t::Output,)+);
            type Ok = ($($t::Output,)+);
            type Err = Error;
        }
    };
}

impl_client_type_for_tuple!(T0);
impl_client_type_for_tuple!(T0, T1);
impl_client_type_for_tuple!(T0, T1, T2);
impl_client_type_for_tuple!(T0, T1, T2, T3);
impl_client_type_for_tuple!(T0, T1, T2, T3, T4);
impl_client_type_for_tuple!(T0, T1, T2, T3, T4, T5);
impl_client_type_for_tuple!(T0, T1, T2, T3, T4, T5, T6);
impl_client_type_for_tuple!(T0, T1, T2, T3, T4, T5, T6, T7);
impl_client_type_for_tuple!(T0, T1, T2, T3, T4, T5, T6, T7, T8);
impl_client_type_for_tuple!(T0, T1, T2, T3, T4, T5, T6, T7, T8, T9);
impl_client_type_for_tuple!(T0, T1, T2, T3, T4, T5, T6, T7, T8, T9, T10);
impl_client_type_for_tuple!(T0, T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11);
